-- Phase 21.x — Built-in Platform Theme Catalog
-- Platform-owned initial catalog. Creator marketplace lifecycle remains separate.
-- No fake user/organization/asset records are used.
-- Declarative 3D World DSL only; no code/script/authority fields.

alter table public.themes alter column created_by_user_id drop not null;
alter table public.theme_versions alter column created_by_user_id drop not null;
alter table public.world_templates alter column created_by_user_id drop not null;
alter table public.world_template_versions alter column created_by_user_id drop not null;

alter table public.themes add column if not exists source text not null default 'creator' check (source in ('creator','platform'));
alter table public.themes add column if not exists catalog_key text;
alter table public.themes add column if not exists catalog_order integer;
alter table public.world_templates add column if not exists source text not null default 'creator' check (source in ('creator','platform'));
alter table public.world_templates add column if not exists catalog_key text;
alter table public.world_templates add column if not exists catalog_order integer;

create unique index if not exists themes_platform_catalog_key_uq on public.themes(catalog_key) where source='platform' and catalog_key is not null;
create unique index if not exists world_templates_platform_catalog_key_uq on public.world_templates(catalog_key) where source='platform' and catalog_key is not null;
create index if not exists themes_source_catalog_order_idx on public.themes(source,catalog_order,updated_at desc);
create index if not exists world_templates_source_catalog_order_idx on public.world_templates(source,catalog_order,updated_at desc);

create or replace function private.theme_owner(p_theme_id uuid) returns boolean language sql stable security definer set search_path=''
as $$ select exists(select 1 from public.themes t where t.id=p_theme_id and t.source='creator' and (t.creator_user_id=auth.uid() or (t.creator_organization_id is not null and exists(select 1 from public.organization_members m where m.organization_id=t.creator_organization_id and m.user_id=auth.uid())))) $$;
revoke all on function private.theme_owner(uuid) from public,anon,authenticated;
create or replace function private.world_template_owner(p_template_id uuid) returns boolean language sql stable security definer set search_path=''
as $$ select exists(select 1 from public.world_templates t where t.id=p_template_id and t.source='creator' and (t.creator_user_id=auth.uid() or (t.creator_organization_id is not null and exists(select 1 from public.organization_members m where m.organization_id=t.creator_organization_id and m.user_id=auth.uid())))) $$;
revoke all on function private.world_template_owner(uuid) from public,anon,authenticated;

